/**
 * CORE-6108 — after the settings-assistant panel navigates to a
 * recommendation's `app_path`, find the exact control (`data-test="<anchor>"`),
 * expand whatever collapsed accordion ancestor hides it, scroll it into view,
 * and briefly highlight it. The target page is rendered by <router-view> in
 * SettingsLayout — a fresh async component load, so the element may not
 * exist in the DOM yet the instant `router.push` resolves; a MutationObserver
 * (not a fixed delay) is what actually waits for it, bounded so a wrong/typo'd
 * anchor doesn't wait forever.
 */

export const ANCHOR_WAIT_TIMEOUT_MS = 5000;
/** CORE-6108 UX review: was 2000ms — long enough to catch a quick glance,
 * not long enough to actually read which control just changed and confirm
 * it's the right one, especially once the highlight moved from just the
 * control itself to its whole row (below). */
export const HIGHLIGHT_DURATION_MS = 4000;
/** Bounded wait for a page-level loading overlay (Quasar's global Loading
 * plugin, or any `[aria-busy="true"]`) to clear before scrolling/
 * highlighting — a highlight applied WHILE a loading overlay still covers
 * the target is invisible, and scrollIntoView measures the wrong position
 * mid-load. */
export const LOADING_OVERLAY_WAIT_TIMEOUT_MS = 3000;
const LOADING_OVERLAY_SELECTOR = '.q-loading, [aria-busy="true"]';
//: Tailwind ring utility classes — the design system's own focus-ring token
//: (--ring / --primary), not a bespoke color. Kept as the REDUCED-MOTION
//: fallback (a static ring, no pulse) and as the always-on highlight for a
//: target too small/inline to carry the row-level pulse sensibly.
export const HIGHLIGHT_CLASSES = ['ring-2', 'ring-primary'] as const;
/** The animated, token-colored background pulse — the DEFAULT highlight
 * style, applied to the target's own "row" ancestor (see
 * `findHighlightTarget`) rather than just the control itself, so the whole
 * setting reads as "this is what changed", not just a small toggle. Skipped
 * under prefers-reduced-motion in favour of HIGHLIGHT_CLASSES' static ring. */
export const PULSE_CLASS = 'settings-assistant-anchor-pulse';
/** Gives a statically positioned target `position: relative` so the pulse overlay can cover it. */
export const HOST_CLASS = 'settings-assistant-anchor-host';

const VOID_ELEMENTS = new Set(['INPUT', 'IMG', 'SELECT', 'TEXTAREA', 'BR', 'HR']);

// Elements that cannot render a ::after overlay hand the highlight to their parent.
function overlayHost(target: HTMLElement): HTMLElement {
  return VOID_ELEMENTS.has(target.tagName) && target.parentElement ? target.parentElement : target;
}

/** Gives the overlay rounded corners when the target itself has none. */
export const ROUNDED_CLASS = 'settings-assistant-anchor-rounded';

function hasNoBorderRadius(el: HTMLElement): boolean {
  const style = window.getComputedStyle(el);
  return [
    style.borderTopLeftRadius,
    style.borderTopRightRadius,
    style.borderBottomRightRadius,
    style.borderBottomLeftRadius,
  ].every((radius) => !radius || parseFloat(radius) === 0);
}

function isStaticallyPositioned(el: HTMLElement): boolean {
  const position = window.getComputedStyle(el).position;
  return !position || position === 'static';
}

function escapeAttrValue(value: string): string {
  if (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') {
    return CSS.escape(value);
  }
  // Fallback (older test/jsdom environments without CSS.escape): escape the
  // characters that would otherwise break out of the attribute selector.
  return value.replace(/["\\]/g, '\\$&');
}

export function findByAnchor(anchor: string): HTMLElement | null {
  if (!anchor) return null;
  return document.querySelector(`[data-test="${escapeAttrValue(anchor)}"]`);
}

/** Resolves with the element once it appears, or null after the timeout. */
export function waitForAnchor(
  anchor: string,
  timeoutMs: number = ANCHOR_WAIT_TIMEOUT_MS,
): Promise<HTMLElement | null> {
  const existing = findByAnchor(anchor);
  if (existing) return Promise.resolve(existing);

  return new Promise((resolve) => {
    let settled = false;
    const finish = (result: HTMLElement | null) => {
      if (settled) return;
      settled = true;
      observer.disconnect();
      clearTimeout(timer);
      resolve(result);
    };
    const observer = new MutationObserver(() => {
      const el = findByAnchor(anchor);
      if (el) finish(el);
    });
    observer.observe(document.body, { childList: true, subtree: true });
    const timer = setTimeout(() => finish(null), timeoutMs);
  });
}

/**
 * Walks up from, AND INCLUDING, `el` expanding every collapsed ancestor it
 * finds — either the standard `aria-expanded="false"` toggle pattern, or
 * the app's own DocbitsAccordionPanel (`.settings-accordion` without
 * `.expanded`). Clicks the real toggle control rather than mutating classes
 * directly, so the component's own (Vue-managed) open/closed state stays in
 * sync — a class added here would just be overwritten on the component's
 * next render.
 *
 * CORE-6108 review (Codex): starting at `el.parentElement` missed the case
 * where `el` itself IS the collapsed wrapper — DocbitsAccordionPanel has no
 * `inheritAttrs: false`, so a `data-test` on the component tag (e.g.
 * `data-test="mfa-requirement-section"` in companyInformation.vue) falls
 * through onto its OWN root `.settings-accordion` element, not a descendant
 * of it. MFA/release-channel/org-domains anchors are exactly this shape —
 * without checking `el` first, those three never actually expanded.
 *
 * CORE-6146: returns whether anything was actually expanded, so the caller
 * knows the layout is about to move (accordion height transition) and must
 * wait for it before measuring/scrolling.
 */
export function expandCollapsedAncestors(el: HTMLElement): boolean {
  let expanded = false;
  let node: HTMLElement | null = el;
  while (node) {
    if (node.getAttribute?.('aria-expanded') === 'false') {
      node.click();
      expanded = true;
    } else if (
      node.classList?.contains('settings-accordion') &&
      !node.classList.contains('expanded')
    ) {
      const header = node.querySelector<HTMLElement>(
        '.settings-accordion-header',
      );
      if (header) {
        header.click();
        expanded = true;
      }
    }
    node = node.parentElement;
  }
  return expanded;
}

/**
 * CORE-6133 — the highlight covers the whole setting: its label, any hint
 * text and the control, up to its card. First widens from the control while
 * the next ancestor holds no OTHER setting control; if that still has no
 * label text (label and control sit in one row with a related sub-control),
 * widens a little further to the nearest ancestor that has one. Never
 * crosses a section boundary (accordion body, tab panel, content area).
 */
const INPUT_CONTROL_SELECTOR = [
  'input:not([type="hidden"])',
  'select',
  'textarea',
  '[role="switch"]',
  '[role="checkbox"]',
  '[role="radio"]',
  '[role="combobox"]',
  '[role="slider"]',
  '.f-toggle',
  '.q-toggle',
  '.q-checkbox',
  '.q-radio',
  '.q-field',
  '.q-slider',
].join(', ');
const CONTROL_SELECTOR = `${INPUT_CONTROL_SELECTOR}, [data-test^="sa-"]`;

const HIGHLIGHT_BOUNDARY_SELECTOR = [
  '.settings-accordion-body',
  '.settings-accordion-content',
  '.q-tab-panel',
  '.q-tab-panels',
  '[data-test="settings-content-area"]',
  'main',
].join(', ');

export const MAX_HIGHLIGHT_LEVELS = 5;
export const MAX_LABEL_SEARCH_LEVELS = 3;

function isBoundary(node: HTMLElement): boolean {
  return (
    node === document.body ||
    node === document.documentElement ||
    node.matches(HIGHLIGHT_BOUNDARY_SELECTOR)
  );
}

function holdsAnotherControl(container: HTMLElement, el: HTMLElement): boolean {
  return Array.from(container.querySelectorAll<HTMLElement>(CONTROL_SELECTOR)).some(
    (control) => !el.contains(control) && !control.contains(el),
  );
}

function hasLabelText(container: HTMLElement): boolean {
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    if (!node.textContent?.trim()) continue;
    const control = node.parentElement?.closest(INPUT_CONTROL_SELECTOR);
    if (!control || !container.contains(control)) return true;
  }
  return false;
}

export function findHighlightTarget(el: HTMLElement): HTMLElement {
  let target = el;
  let node = el.parentElement;
  for (let level = 0; node && level < MAX_HIGHLIGHT_LEVELS; level++) {
    if (isBoundary(node) || holdsAnotherControl(node, el)) break;
    target = node;
    node = node.parentElement;
  }
  if (hasLabelText(target)) return target;

  let candidate = target.parentElement;
  for (let level = 0; candidate && level < MAX_LABEL_SEARCH_LEVELS; level++) {
    if (isBoundary(candidate)) break;
    if (hasLabelText(candidate)) return candidate;
    candidate = candidate.parentElement;
  }
  return target;
}

/**
 * Bounded wait for a page-level loading overlay to clear (Quasar's global
 * Loading plugin's `.q-loading`, or any `[aria-busy="true"]`) — a highlight
 * applied while one still covers the target is invisible, and
 * scrollIntoView measures the wrong position mid-load. Resolves
 * immediately (the common case) when nothing matches right now.
 *
 * Codex review (2026-09-29): this used to resolve `void` either way, so a
 * caller had no way to tell "the overlay actually cleared" apart from
 * "gave up after the timeout, it's still there" — both looked identical.
 * Returns `true`/`false` for that distinction now; `jumpToAnchor` proceeds
 * with its scroll/highlight regardless of which one it gets (a highlight
 * the admin can at least partially see through a stuck overlay is still a
 * more useful fallback than silently doing nothing), but the distinction
 * is now observable rather than swallowed, for callers or tests that need
 * it.
 */
export function waitForLoadingOverlayGone(
  timeoutMs: number = LOADING_OVERLAY_WAIT_TIMEOUT_MS,
): Promise<boolean> {
  if (!document.querySelector(LOADING_OVERLAY_SELECTOR)) {
    return Promise.resolve(true);
  }
  return new Promise((resolve) => {
    let settled = false;
    const finish = (cleared: boolean) => {
      if (settled) return;
      settled = true;
      observer.disconnect();
      clearTimeout(timer);
      resolve(cleared);
    };
    const observer = new MutationObserver(() => {
      if (!document.querySelector(LOADING_OVERLAY_SELECTOR)) finish(true);
    });
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['aria-busy', 'class'],
    });
    const timer = setTimeout(() => finish(false), timeoutMs);
  });
}

export function prefersReducedMotion(): boolean {
  return (
    typeof window !== 'undefined' &&
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  );
}

async function nextFrame(): Promise<void> {
  await oneFrame();
  await oneFrame();
}

export const LAYOUT_STABLE_TIMEOUT_MS = 1200;
export const LAYOUT_STABLE_FRAMES = 3;
export const SCROLL_SETTLE_TIMEOUT_MS = 700;

/** One animation frame — or, when frames never come (background tab, suspended
 * frame source), a short timeout, so no frame wait can block forever. */
const FRAME_FALLBACK_MS = 50;
function oneFrame(): Promise<void> {
  return new Promise((resolve) => {
    const hasRaf = typeof requestAnimationFrame === 'function';
    const timer = setTimeout(resolve, hasRaf ? FRAME_FALLBACK_MS : 0);
    if (hasRaf) {
      requestAnimationFrame(() => {
        clearTimeout(timer);
        resolve();
      });
    }
  });
}

function layoutSignature(el: HTMLElement): string {
  const rect = el.getBoundingClientRect();
  return `${rect.top}|${rect.height}`;
}

/**
 * CORE-6146: after a collapsed accordion was expanded its height transition
 * is still running, so `el` is measured at its pre-expansion position —
 * scrollIntoView then sees it as already in view and does nothing, and the
 * element ends up far below the fold once the transition finishes. Resolves
 * once the element's top/height were unchanged for `stableFrames` frames in
 * a row. Bounded by `timeoutMs` so a never-settling layout (or a hidden/
 * detached element, whose rect is constant zeros and so settles at once)
 * can never hang the deep link. Returns whether the layout settled.
 */
export async function waitForLayoutStable(
  el: HTMLElement,
  timeoutMs: number = LAYOUT_STABLE_TIMEOUT_MS,
  stableFrames: number = LAYOUT_STABLE_FRAMES,
): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  let last = layoutSignature(el);
  let stable = 0;
  while (Date.now() < deadline) {
    await oneFrame();
    const current = layoutSignature(el);
    stable = current === last ? stable + 1 : 0;
    last = current;
    if (stable >= stableFrames) return true;
  }
  return false;
}

/**
 * Only transitions are waited for: an infinite CSSAnimation (spinner, the
 * highlight pulse of a previous jump, skeleton shimmer) would otherwise hold
 * the wait to its timeout.
 */
function isCssTransition(animation: Animation): boolean {
  return typeof CSSTransition !== 'undefined'
    ? animation instanceof CSSTransition
    : 'transitionProperty' in animation;
}

/**
 * CORE-6146: the accordion opens with a CSS `max-height` transition. The
 * target's top stays constant while it runs (so waitForLayoutStable is fooled
 * — measured in a real browser), but the scroll container's scrollHeight only
 * grows with the animation, so a scrollIntoView started early is clamped to
 * the small max scroll of that moment. Waits one frame (so the transitions
 * exist), then for every running Web Animation/CSS transition on `el` and its
 * ancestors to finish, bounded by `timeoutMs`, then one more frame. Never
 * throws or hangs. `getAnimations` is missing in jsdom/older browsers — there
 * the layout-stability wait is the fallback. Returns whether everything
 * finished (or there was nothing to wait for) within the bound.
 */
export function waitForTransitionsDone(
  el: HTMLElement,
  timeoutMs: number = LAYOUT_STABLE_TIMEOUT_MS,
): Promise<boolean> {
  // The WHOLE wait (frames, collection, finished promises, fallback) is
  // raced against the bound; the inner run has no side effects, so once the
  // bound wins its leftovers can only finish unobserved.
  let timer: ReturnType<typeof setTimeout> | undefined;
  return Promise.race([
    transitionsDone(el, timeoutMs),
    new Promise<boolean>((resolve) => {
      timer = setTimeout(() => resolve(false), timeoutMs);
    }),
  ]).finally(() => clearTimeout(timer));
}

async function transitionsDone(el: HTMLElement, timeoutMs: number): Promise<boolean> {
  if (typeof el.getAnimations !== 'function') {
    return waitForLayoutStable(el, timeoutMs);
  }
  await oneFrame();
  const finished: Promise<unknown>[] = [];
  for (let node: HTMLElement | null = el; node; node = node.parentElement) {
    try {
      // A wrapper anchor IS the `.settings-accordion` root while the
      // max-height transition runs on its child `.settings-accordion-content`,
      // so accordions are scanned with `subtree`.
      const animations = node.matches?.('.settings-accordion')
        ? node.getAnimations?.({ subtree: true })
        : node.getAnimations?.();
      for (const animation of animations ?? []) {
        if (isCssTransition(animation)) {
          finished.push(animation.finished.catch(() => undefined));
        }
      }
    } catch {
      // a node that cannot report its animations is simply not waited for
    }
  }
  await Promise.all(finished);
  await oneFrame();
  return true;
}

function isScrollContainer(node: HTMLElement): boolean {
  const { overflowY, overflowX } = window.getComputedStyle(node);
  return /(auto|scroll|overlay)/.test(`${overflowY} ${overflowX}`);
}

/**
 * Whether the centre of `el` is inside the viewport and inside the visible
 * box of every scroll container above it. An element without a box (hidden,
 * detached, jsdom has no layout) cannot be judged, so it counts as visible —
 * there is nothing a further scroll could fix.
 */
export function isElementVisibleInScrollers(el: HTMLElement): boolean {
  const rect = el.getBoundingClientRect();
  if (rect.width === 0 && rect.height === 0) return true;
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;
  const inside = (box: { top: number; bottom: number; left: number; right: number }) =>
    y >= box.top && y <= box.bottom && x >= box.left && x <= box.right;
  if (
    !inside({ top: 0, left: 0, bottom: window.innerHeight, right: window.innerWidth })
  ) {
    return false;
  }
  for (let node = el.parentElement; node; node = node.parentElement) {
    if (isScrollContainer(node) && !inside(node.getBoundingClientRect())) {
      return false;
    }
  }
  return true;
}

/** Bumped by every jumpToAnchor; everything an older jump still has pending must stand down. */
let jumpGeneration = 0;

/** Makes every pending scroll correction stand down (a newer jump started; test teardown). */
export function cancelScrollCorrections(): void {
  jumpGeneration++;
}

/**
 * CORE-6146 backstop: the accordion transitions are awaited before the
 * scroll, so this only catches what that cannot know (e.g. lazily rendered
 * content growing after the scroll). After a bounded wait for the smooth
 * scroll to finish, scrolls ONCE more without animation if the element is
 * still not visible. Accepted trade-off: a user who scrolls manually within
 * those ~700 ms can be pulled back once — no intent listeners, kept simple.
 * A newer jump cancels it via the generation counter. Returns whether the
 * element was visible (no correction needed).
 */
export async function ensureScrolledIntoView(
  el: HTMLElement,
  generation: number = jumpGeneration,
): Promise<boolean> {
  if (generation !== jumpGeneration) return false;
  await new Promise((resolve) => setTimeout(resolve, SCROLL_SETTLE_TIMEOUT_MS));
  if (generation !== jumpGeneration) return false;
  if (!el.isConnected || isElementVisibleInScrollers(el)) return true;
  el.scrollIntoView({ behavior: 'auto', block: 'center' });
  return false;
}

interface ActiveHighlight {
  target: HTMLElement;
  classes: string[];
  timer?: ReturnType<typeof setTimeout>;
}
/** The one highlight currently shown — a new jump replaces it, and only its owner's timer may clear it. */
let activeHighlight: ActiveHighlight | null = null;

function clearActiveHighlight(): void {
  if (!activeHighlight) return;
  clearTimeout(activeHighlight.timer);
  activeHighlight.target.classList.remove(...activeHighlight.classes);
  activeHighlight = null;
}

/**
 * The whole sequence: wait for the anchor AND any page-level loading
 * overlay to clear, expand its collapsed ancestors, scroll it into view,
 * and apply a ~4s highlight to the whole setting row (not just the
 * control) — a token-colored pulse by default, a static ring under
 * prefers-reduced-motion, then move keyboard focus to the control (see
 * focusAnchorControl). Returns whether the anchor was found at all
 * (false = gave up after ANCHOR_WAIT_TIMEOUT_MS — the caller still
 * navigated, it just can't point at the exact control).
 */
export async function jumpToAnchor(
  anchor: string | null | undefined,
  timeoutMs: number = ANCHOR_WAIT_TIMEOUT_MS,
): Promise<boolean> {
  cancelScrollCorrections();
  const generation = jumpGeneration;
  // A newer jump owns scroll, highlight and focus from the moment it starts:
  // after EVERY wait below an older jump must stand down, or it scrolls,
  // highlights and steals focus AFTER the newer one.
  const superseded = () => generation !== jumpGeneration;
  if (!anchor) return false;
  const firstEl = await waitForAnchor(anchor, timeoutMs);
  if (!firstEl || superseded()) return false;

  await waitForLoadingOverlayGone();
  if (superseded()) return false;

  // Codex review (2026-09-29): a loading overlay covering the page is
  // frequently covering a full re-render underneath it — `firstEl` (found
  // BEFORE the wait) can be a detached node by the time the overlay
  // clears, with a brand new element now matching the same anchor.
  // Re-resolving here picks up that replacement; `?? firstEl` is the
  // fallback for the (rarer) case where the overlay simply never cleared
  // and nothing changed underneath it — acting on the original element is
  // still strictly better than giving up silently. A detached `firstEl`
  // with no replacement is NOT such a fallback — scrolling/highlighting a
  // node that is no longer in the document does nothing visible, so that
  // case reports "not found" instead of a false success.
  const el = findByAnchor(anchor) ?? (firstEl.isConnected ? firstEl : null);
  if (!el) return false;
  const expanded = expandCollapsedAncestors(el);
  // Let the (now expanded) layout reflow before measuring scroll position —
  // otherwise scrollIntoView can target where the element WAS about to be,
  // mid-accordion-transition. Two frames are not enough for the accordion's
  // height transition (CORE-6146), so after an expansion wait for the
  // running transitions to finish (layout-stability fallback without
  // getAnimations).
  if (expanded) await waitForTransitionsDone(el);
  if (superseded()) return false;
  //
  // The same frame wait also covers overlay mode (<1280px): the page is
  // `inert` while the modal panel is open, and the panel closes itself
  // before navigating there (SettingsAssistantPanel.goToSetting). Waiting
  // for `inert` to clear — at least one frame, so the closing layout's own
  // next-tick toggle-focus restoration has already run — means the focus
  // set at the end of this function is not immediately stolen or refused.
  await waitForInertCleared(el);
  if (superseded()) return false;

  el.scrollIntoView({
    behavior: prefersReducedMotion() ? 'auto' : 'smooth',
    block: 'center',
  });
  // Not awaited: the highlight and focus must not wait for the scroll to
  // settle. The correction only re-scrolls if the element ended up outside
  // the visible area.
  void ensureScrolledIntoView(el, generation).catch(() => undefined);

  highlightElement(el);

  focusAnchorControl(el);

  return true;
}

/**
 * The pulse on the element's whole row (label, hint and control). Also used
 * by the validation assistant's "Go to field" (CORE-6161).
 */
export function highlightElement(el: HTMLElement): void {
  // Before measuring: a previous highlight of this same target may still
  // carry HOST_CLASS (its position:relative), which would make the target
  // look non-static and drop HOST_CLASS from the new highlight.
  clearActiveHighlight();
  const target = overlayHost(findHighlightTarget(el));
  const reducedMotion = prefersReducedMotion();
  const classes: string[] = reducedMotion ? [...HIGHLIGHT_CLASSES] : [PULSE_CLASS];
  if (!reducedMotion && isStaticallyPositioned(target)) classes.push(HOST_CLASS);
  if (!reducedMotion && hasNoBorderRadius(target)) classes.push(ROUNDED_CLASS);
  target.classList.add(...classes);
  const owner: ActiveHighlight = { target, classes };
  activeHighlight = owner;
  // clearActiveHighlight() cancels this timer, so a replaced highlight's timer never fires.
  owner.timer = setTimeout(clearActiveHighlight, HIGHLIGHT_DURATION_MS);
}

export const INERT_CLEAR_WAIT_TIMEOUT_MS = 1000;

/**
 * Resolves true once `el` no longer sits inside an `[inert]` subtree, false
 * after `timeoutMs` (bounded — a background that stays inert must never
 * hang the deep link). Always yields at least one frame before resolving,
 * so anything the closing layout schedules for its next tick (e.g. putting
 * focus back on the assistant toggle) has already run and can't steal the
 * focus we are about to set.
 */
export async function waitForInertCleared(
  el: HTMLElement,
  timeoutMs: number = INERT_CLEAR_WAIT_TIMEOUT_MS,
): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  do {
    await nextFrame();
    if (!el.closest('[inert]')) return true;
  } while (Date.now() < deadline);
  return false;
}

const FOCUSABLE_CONTROL_SELECTOR =
  'input:not([type="hidden"]):not([disabled]), select:not([disabled]), textarea:not([disabled]), button:not([disabled]), [tabindex]:not([tabindex="-1"]), [role="switch"], [role="checkbox"], [role="combobox"]';

/**
 * CORE-6108 (Codex review, 2026-09-29): a deep-link click used to leave
 * keyboard focus on the panel's "Zur Einstellung" button — a keyboard/
 * screen-reader user saw the page scroll but had to Tab through the whole
 * page to reach the highlighted setting. Moves focus to the control itself
 * (the anchor element when it is focusable, else its first focusable
 * descendant — `f-toggle`'s root is a wrapper, the real switch is inside).
 *
 * Deliberately a no-op (focus stays on the button, a sensible target) when
 * no focusable control exists, or when the control sits inside an `inert`
 * subtree — that is the <1280px modal-overlay case, where the panel traps
 * focus and the page behind it cannot take focus anyway. `preventScroll`
 * because jumpToAnchor already scrolled it into the centre. Returns whether
 * focus actually moved.
 */
export function focusAnchorControl(el: HTMLElement): boolean {
  const control = el.matches(FOCUSABLE_CONTROL_SELECTOR)
    ? el
    : el.querySelector<HTMLElement>(FOCUSABLE_CONTROL_SELECTOR);
  if (!control || control.closest('[inert], [aria-hidden="true"]')) {
    return false;
  }
  control.focus({ preventScroll: true });
  return document.activeElement === control;
}
